const items = $input.all().map(i => i.json).filter(j => j.noticeId);
if (!items.length) return [];
const esc = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const link = j => /^https:\/\/sam\.gov\//.test(j.samUrl || '') ? `<${j.samUrl}|${esc(j.title)}>` : esc(j.title);
const lines = items.slice(0, 25).map(j => {
  const due = j.responseDeadline ? esc(j.responseDeadline.slice(0, 10)) : 'n/a';
  const aside = j.setAside ? ` | ${esc(j.setAside)}` : '';
  return `• ${link(j)}\n   ${esc(j.noticeType)} | ${esc(j.department)} | NAICS ${esc(j.naicsCode || '-')}${aside} | due ${due}`;
});
const more = items.length > 25 ? `\n…and ${items.length - 25} more` : '';
return [{ json: { text: `*${items.length} new SAM.gov opportunities*\n${lines.join('\n')}${more}` } }];
